function dispatch(msg) {
  if (!msg) return;
  const result = update(model, msg);
  model = result[0];
  render(model);
  if (result[1]) run(result[1]);
}

async function run(cmd) {
  if (!cmd) return;
  if (cmd.__gothicBatch) {
    await Promise.all(cmd.__gothicBatch.map((sub) => run(sub)));
    return;
  }
  if (cmd.__gothicSequence) {
    for (const sub of cmd.__gothicSequence) {
      await run(sub);
    }
    return;
  }
  const msg = await cmd();
  if (msg) {
    dispatch(msg);
  }
}

function emit(msg) { dispatch(msg); }

function init() {
  return null;
}

function update(m, msg) {
  switch (msg.tag) {
  case "LocationChanged":
  {
    m.Path = msg.Path;
    m.Page = "notfound";
    switch (msg.Path) {
    case "/":
      m.Page = "overview";
      break;
    case "/button":
      m.Page = "button";
      break;
    case "/field":
      m.Page = "field";
      break;
    case "/tabs":
      m.Page = "tabs";
      break;
    case "/accordion":
      m.Page = "accordion";
      break;
    case "/combobox":
      m.Page = "combobox";
      break;
    }
    break;
  }
  case "IncrementClicked":
  {
    return [m, async () => {
  let count, err;
  try {
    count = await Increment();
  } catch (__gothicErr1) {
    err = __gothicErr1;
  }
  if (err != null) {
    return {tag: "CountFailed", Message: err.message};
  }
  return {tag: "CountLoaded", Count: count};
}];
    break;
  }
  case "CountLoaded":
  {
    m.Count = msg.Count;
    m.message = "";
    break;
  }
  case "CountFailed":
  {
    m.message = msg.Message;
    break;
  }
  case "NameChanged":
  {
    m.Name = msg.Text;
    if (String(msg.Text).trim() == "") {
      m.NameError = "Enter your name.";
    } else {
      m.NameError = "";
    }
    break;
  }
  case "DoneChanged":
  {
    m.Done = !m.Done;
    break;
  }
  case "NotifyChanged":
  {
    m.Notify = !m.Notify;
    break;
  }
  case "TabClicked":
  {
    m.ActiveTab = msg.ID;
    break;
  }
  case "TabKey":
  {
    const index = 0;
    for (const [i, tab] of entries(m.Tabs)) {
      if (tab.ID == m.ActiveTab) {
        index = i;
      }
    }
    if (msg.Key == "ArrowRight") {
      index = (index + 1) % len(m.Tabs);
    }
    m.ActiveTab = m.Tabs[index].ID;
    break;
  }
  case "AccordionClicked":
  {
    if (m.OpenAccordion == msg.ID) {
      m.OpenAccordion = "";
    } else {
      m.OpenAccordion = msg.ID;
    }
    break;
  }
  case "ComboboxValueChanged":
  {
    m.FruitValue = msg.Value;
    m.FruitLabel = msg.Label;
    break;
  }
  case "ComboboxValuesChanged":
  {
    m.FruitValues = msg.Values;
    m.FruitValueLabels = msg.Labels;
    break;
  }
  }
  return [m, null];
}

